/***********************************************************************************************************************
 * Builds the first screen: SquareLine's ui_init(), or the built-in test screen without an export.
 *
 * @param[in,out] p_ctrl  Pointer to the caller-owned runtime control block.
 * @param[in]     p_cfg   Configuration that remains valid and unchanged for the lifetime of the instance.
 *
 * @retval APP_SUCCESS              The screen is loaded.
 * @retval APP_ERR_INVALID_POINTER  A required API argument is NULL.
 * @retval APP_ERR_INVALID_STATE    The control block is already initialized, or the LVGL port is not.
 * @retval APP_ERR_TIMEOUT          The LVGL lock was not available.
 **********************************************************************************************************************/
app_err_t ui_service_init(ui_service_instance_ctrl_t *const p_ctrl, const ui_service_config_t *const p_cfg)
{
#if UI_SERVICE_CFG_PARAMETER_CHECKING
    APP_ASSERT(NULL != p_ctrl);
    APP_ASSERT(NULL != p_cfg);
    APP_ASSERT(NULL != p_cfg->p_lvgl);
    APP_ERROR_RETURN(false == p_ctrl->init, APP_ERR_INVALID_STATE);
#endif

    const app_err_t ret = lvgl_port_lock(p_cfg->p_lvgl, UI_SERVICE_INIT_LOCK_TIMEOUT_MS);
    if (APP_SUCCESS != ret)
    {
        return ret;
    }

    ui_init();
#if UI_SERVICE_HAS_SQUARELINE
    ui_service_overlay_attach();
    ui_service_inputs_attach(p_ctrl);
    ui_service_inputs_reset(lvgl_port_get_group(p_cfg->p_lvgl), UI_SERVICE_SCREEN_HOME, false);
#endif
    lvgl_port_unlock(p_cfg->p_lvgl);

    p_ctrl->p_cfg = p_cfg;
    p_ctrl->init  = true;

    ESP_LOGI(UI_SERVICE_TAG,
             "%s",
             ui_service_has_squareline() ? "SquareLine UI loaded"
                                         : "No SquareLine export in app/ui_service/ui: test screen");
    return APP_SUCCESS;
}

/***********************************************************************************************************************
 * Reports whether the build contains a SquareLine export (decided by app/ui_service/CMakeLists.txt).
 **********************************************************************************************************************/
bool ui_service_has_squareline(void)
{
    return (0 != UI_SERVICE_HAS_SQUARELINE);
}

/***********************************************************************************************************************
 * Shows a SquareLine screen and gives the keypad's group only that screen's text areas: every text area joins the
 * default group when created, and keys must not reach one on a hidden screen (# there would submit it). Home keeps
 * ui_InputField so the digit that leaves Home is not lost. What a screen says is set by the caller under
 * ui_service_lock(), and checking a PIN or admin password stays with the caller, done locally, never over MQTT.
 *
 * @param[in,out] p_ctrl  Pointer to an initialized runtime control block.
 * @param[in]     screen  Screen to show.
 *
 * @retval APP_SUCCESS               The screen is shown.
 * @retval APP_ERR_INVALID_POINTER   The control pointer is NULL.
 * @retval APP_ERR_INVALID_STATE     The control block is not initialized.
 * @retval APP_ERR_INVALID_ARGUMENT  Unknown screen.
 * @retval APP_ERR_NOT_SUPPORTED     The build has no SquareLine export (test screen only).
 * @retval APP_ERR_TIMEOUT           The LVGL lock was not available.
 **********************************************************************************************************************/
app_err_t ui_service_show(ui_service_instance_ctrl_t *const p_ctrl, ui_service_screen_t screen)
{
#if UI_SERVICE_CFG_PARAMETER_CHECKING
    APP_ASSERT(NULL != p_ctrl);
    APP_ERROR_RETURN(true == p_ctrl->init, APP_ERR_INVALID_STATE);
#endif

#if UI_SERVICE_HAS_SQUARELINE
    lv_obj_t **pp_screen;
    void (*p_init)(void);

    switch (screen)
    {
        case UI_SERVICE_SCREEN_HOME:
            pp_screen = &ui_Home;
            p_init    = &ui_Home_screen_init;
            break;
        case UI_SERVICE_SCREEN_INPUT:
            pp_screen = &ui_Input;
            p_init    = &ui_Input_screen_init;
            break;
        case UI_SERVICE_SCREEN_VOICE:
            pp_screen = &ui_Voice;
            p_init    = &ui_Voice_screen_init;
            break;
        case UI_SERVICE_SCREEN_ADMIN_LOGIN:
            pp_screen = &ui_AdminLogin;
            p_init    = &ui_AdminLogin_screen_init;
            break;
        case UI_SERVICE_SCREEN_MENU:
            pp_screen = &ui_Menu;
            p_init    = &ui_Menu_screen_init;
            break;
        case UI_SERVICE_SCREEN_STATUS:
            pp_screen = &ui_Status;
            p_init    = &ui_Status_screen_init;
            break;
        default:
            return APP_ERR_INVALID_ARGUMENT;
    }

    const app_err_t ret = lvgl_port_lock(p_ctrl->p_cfg->p_lvgl, UI_SERVICE_SCREEN_LOCK_TIMEOUT_MS);
    if (APP_SUCCESS != ret)
    {
        return ret;
    }

    /* Keys the caller is reacting to belong to the screen they were pressed on: a 0 leaving the admin menu must not
     * reach the PIN field on Home. Digits typed on Home went to ui_InputField; the first one is what makes the caller
     * show Input. */
    lvgl_port_process_keys(p_ctrl->p_cfg->p_lvgl);
    const bool keep_input = (UI_SERVICE_SCREEN_INPUT == screen) && (lv_scr_act() == ui_Home);

    if (lv_scr_act() != *pp_screen)
    {
        _ui_screen_change(pp_screen, LV_SCR_LOAD_ANIM_NONE, 0, 0, p_init);
    }
    ui_service_inputs_reset(lvgl_port_get_group(p_ctrl->p_cfg->p_lvgl), screen, keep_input);
    lvgl_port_unlock(p_ctrl->p_cfg->p_lvgl);
    return APP_SUCCESS;
#else
    (void)screen;
    return APP_ERR_NOT_SUPPORTED;
#endif
}

/***********************************************************************************************************************
 * Sets the function told about # on Input and AdminLogin. Works without a SquareLine export too (it is then never
 * called).
 *
 * @param[in,out] p_ctrl     Pointer to an initialized runtime control block.
 * @param[in]     p_cb       Function to call, or NULL for none.
 * @param[in]     p_context  Passed back to p_cb unchanged.
 *
 * @retval APP_SUCCESS              The function is set.
 * @retval APP_ERR_INVALID_POINTER  The control pointer is NULL.
 * @retval APP_ERR_INVALID_STATE    The control block is not initialized.
 * @retval APP_ERR_TIMEOUT          The LVGL lock was not available.
 **********************************************************************************************************************/
app_err_t ui_service_set_submit_cb(ui_service_instance_ctrl_t *const p_ctrl,
                                   ui_service_submit_cb_t            p_cb,
                                   void                             *p_context)
{
#if UI_SERVICE_CFG_PARAMETER_CHECKING
    APP_ASSERT(NULL != p_ctrl);
    APP_ERROR_RETURN(true == p_ctrl->init, APP_ERR_INVALID_STATE);
#endif

    /* The LVGL task reads both fields, so they change together under the lock. */
    const app_err_t ret = lvgl_port_lock(p_ctrl->p_cfg->p_lvgl, UI_SERVICE_SCREEN_LOCK_TIMEOUT_MS);
    if (APP_SUCCESS != ret)
    {
        return ret;
    }

    p_ctrl->p_submit_cb      = p_cb;
    p_ctrl->p_submit_context = p_context;
    lvgl_port_unlock(p_ctrl->p_cfg->p_lvgl);
    return APP_SUCCESS;
}

/***********************************************************************************************************************
 * Shows the popup above the current screen. A new popup replaces the one showing and restarts its timer.
 *
 * @param[in,out] p_ctrl       Pointer to an initialized runtime control block.
 * @param[in]     level        Background color and icon.
 * @param[in]     p_title      First line, e.g. "Authentication failed".
 * @param[in]     p_detail     Second line, e.g. "3 tries left", or NULL for none.
 * @param[in]     duration_ms  Time before it hides itself; 0 keeps it until ui_service_popup_hide().
 *
 * @retval APP_SUCCESS               The popup is shown.
 * @retval APP_ERR_INVALID_POINTER   The control pointer or title is NULL.
 * @retval APP_ERR_INVALID_STATE     The control block is not initialized.
 * @retval APP_ERR_INVALID_ARGUMENT  Unknown level.
 * @retval APP_ERR_NOT_SUPPORTED     The build has no SquareLine export (test screen only).
 * @retval APP_ERR_TIMEOUT           The LVGL lock was not available.
 **********************************************************************************************************************/
app_err_t ui_service_popup(ui_service_instance_ctrl_t *const p_ctrl,
                           ui_service_popup_level_t          level,
                           const char                       *p_title,
                           const char                       *p_detail,
                           uint32_t                          duration_ms)
{
#if UI_SERVICE_CFG_PARAMETER_CHECKING
    APP_ASSERT(NULL != p_ctrl);
    APP_ASSERT(NULL != p_title);
    APP_ERROR_RETURN(true == p_ctrl->init, APP_ERR_INVALID_STATE);
#endif

#if UI_SERVICE_HAS_SQUARELINE
    uint32_t    color;
    const char *p_icon;

    switch (level)
    {
        case UI_SERVICE_POPUP_INFO:
            color  = UI_SERVICE_POPUP_COLOR_INFO;
            p_icon = LV_SYMBOL_BELL;
            break;
        case UI_SERVICE_POPUP_SUCCESS:
            color  = UI_SERVICE_POPUP_COLOR_SUCCESS;
            p_icon = LV_SYMBOL_OK;
            break;
        case UI_SERVICE_POPUP_ERROR:
            color  = UI_SERVICE_POPUP_COLOR_ERROR;
            p_icon = LV_SYMBOL_CLOSE;
            break;
        default:
            return APP_ERR_INVALID_ARGUMENT;
    }

    const app_err_t ret = lvgl_port_lock(p_ctrl->p_cfg->p_lvgl, UI_SERVICE_SCREEN_LOCK_TIMEOUT_MS);
    if (APP_SUCCESS != ret)
    {
        return ret;
    }

    lv_obj_set_style_bg_color(ui_Popup, lv_color_hex(color), LV_PART_MAIN | LV_STATE_DEFAULT);
    lv_label_set_text(ui_PopupIcon, p_icon);
    lv_label_set_text(ui_PopupTitle, p_title);
    lv_label_set_text(ui_PopupDetail, (NULL != p_detail) ? p_detail : "");
    lv_obj_clear_flag(ui_Popup, LV_OBJ_FLAG_HIDDEN);

    if (0U == duration_ms)
    {
        lv_timer_pause(s_p_popup_timer);
    }
    else
    {
        lv_timer_set_period(s_p_popup_timer, duration_ms);
        lv_timer_reset(s_p_popup_timer);
        lv_timer_resume(s_p_popup_timer);
    }

    lvgl_port_unlock(p_ctrl->p_cfg->p_lvgl);
    return APP_SUCCESS;
#else
    (void)level;
    (void)p_detail;
    (void)duration_ms;
    return APP_ERR_NOT_SUPPORTED;
#endif
}

/***********************************************************************************************************************
 * Hides the popup now. Harmless when none is showing.
 *
 * @param[in,out] p_ctrl  Pointer to an initialized runtime control block.
 *
 * @retval APP_SUCCESS              The popup is hidden.
 * @retval APP_ERR_INVALID_POINTER  The control pointer is NULL.
 * @retval APP_ERR_INVALID_STATE    The control block is not initialized.
 * @retval APP_ERR_NOT_SUPPORTED    The build has no SquareLine export (test screen only).
 * @retval APP_ERR_TIMEOUT          The LVGL lock was not available.
 **********************************************************************************************************************/
app_err_t ui_service_popup_hide(ui_service_instance_ctrl_t *const p_ctrl)
{
#if UI_SERVICE_CFG_PARAMETER_CHECKING
    APP_ASSERT(NULL != p_ctrl);
    APP_ERROR_RETURN(true == p_ctrl->init, APP_ERR_INVALID_STATE);
#endif

#if UI_SERVICE_HAS_SQUARELINE
    const app_err_t ret = lvgl_port_lock(p_ctrl->p_cfg->p_lvgl, UI_SERVICE_SCREEN_LOCK_TIMEOUT_MS);
    if (APP_SUCCESS != ret)
    {
        return ret;
    }

    lv_timer_pause(s_p_popup_timer);
    lv_obj_add_flag(ui_Popup, LV_OBJ_FLAG_HIDDEN);
    lvgl_port_unlock(p_ctrl->p_cfg->p_lvgl);
    return APP_SUCCESS;
#else
    return APP_ERR_NOT_SUPPORTED;
#endif
}

/***********************************************************************************************************************
 * Maps one 4x3 keypad character to an LVGL key and queues it for the focused object.
 *
 * @param[in,out] p_ctrl  Pointer to an initialized runtime control block.
 * @param[in]     key     '0'-'9', UI_SERVICE_KEY_CHAR_ENTER or UI_SERVICE_KEY_CHAR_BACKSPACE.
 *
 * @retval APP_SUCCESS               The key was queued.
 * @retval APP_ERR_INVALID_POINTER   The control pointer is NULL.
 * @retval APP_ERR_INVALID_STATE     The control block is not initialized.
 * @retval APP_ERR_INVALID_ARGUMENT  The character is not a keypad key.
 * @retval APP_ERR_TIMEOUT           The key queue is full; the key was dropped.
 **********************************************************************************************************************/
app_err_t ui_service_post_keypad_char(ui_service_instance_ctrl_t *const p_ctrl, char key)
{
#if UI_SERVICE_CFG_PARAMETER_CHECKING
    APP_ASSERT(NULL != p_ctrl);
    APP_ERROR_RETURN(true == p_ctrl->init, APP_ERR_INVALID_STATE);
#endif

    uint32_t lv_key;

    if ((key >= '0') && (key <= '9'))
    {
        lv_key = (uint32_t)key;
    }
    else if (UI_SERVICE_KEY_CHAR_ENTER == key)
    {
        lv_key = LV_KEY_ENTER;
    }
    else if (UI_SERVICE_KEY_CHAR_BACKSPACE == key)
    {
        lv_key = LV_KEY_BACKSPACE;
    }
    else
    {
        return APP_ERR_INVALID_ARGUMENT;
    }

    return lvgl_port_post_key(p_ctrl->p_cfg->p_lvgl, lv_key);
}

/***********************************************************************************************************************
 * Takes the LVGL lock for changing UI objects from a task other than the LVGL task. See lvgl_port_lock().
 **********************************************************************************************************************/
app_err_t ui_service_lock(ui_service_instance_ctrl_t *const p_ctrl, uint32_t timeout_ms)
{
#if UI_SERVICE_CFG_PARAMETER_CHECKING
    APP_ASSERT(NULL != p_ctrl);
    APP_ERROR_RETURN(true == p_ctrl->init, APP_ERR_INVALID_STATE);
#endif

    return lvgl_port_lock(p_ctrl->p_cfg->p_lvgl, timeout_ms);
}

/***********************************************************************************************************************
 * Releases the lock taken by ui_service_lock().
 **********************************************************************************************************************/
void ui_service_unlock(ui_service_instance_ctrl_t *const p_ctrl)
{
    if ((NULL != p_ctrl) && p_ctrl->init)
    {
        lvgl_port_unlock(p_ctrl->p_cfg->p_lvgl);
    }
}

/***********************************************************************************************************************
 * Private APIs
 **********************************************************************************************************************/

#if UI_SERVICE_HAS_SQUARELINE
/***********************************************************************************************************************
 * The Overlay screen is never shown: it only lets TopBar and Popup be drawn in SquareLine. They move to LVGL's top
 * layer, above every screen, so there is one top bar to update instead of one per screen. Called under the lock.
 **********************************************************************************************************************/
static void ui_service_overlay_attach(void)
{
    lv_obj_set_parent(ui_TopBar, lv_layer_top());
    lv_obj_set_parent(ui_Popup, lv_layer_top());
    lv_obj_add_flag(ui_Popup, LV_OBJ_FLAG_HIDDEN);

    /* Only the now empty screen is deleted; ui_TopBar, ui_Popup and their children stay valid. */
    lv_obj_del(ui_Overlay);
    ui_Overlay = NULL;

    s_p_popup_timer = lv_timer_create(ui_service_popup_timer_cb, 1000U, NULL);
    lv_timer_pause(s_p_popup_timer);
}

/***********************************************************************************************************************
 * Hides a timed popup. Runs in the LVGL task, which already holds the lock.
 **********************************************************************************************************************/
static void ui_service_popup_timer_cb(lv_timer_t *p_timer)
{
    lv_timer_pause(p_timer);
    lv_obj_add_flag(ui_Popup, LV_OBJ_FLAG_HIDDEN);
}

/***********************************************************************************************************************
 * # (LV_KEY_ENTER) on a one-line text area sends LV_EVENT_READY. On Input it submits. AdminLogin has two text areas
 * and the keypad has no arrow keys: # on the ID moves to the password, # on the password submits both,
 * * (LV_KEY_BACKSPACE) on an empty password moves back. Called under the lock.
 **********************************************************************************************************************/
static void ui_service_inputs_attach(ui_service_instance_ctrl_t *const p_ctrl)
{
    lv_obj_add_event_cb(ui_InputField, ui_service_input_ready_cb, LV_EVENT_READY, p_ctrl);
    lv_obj_add_event_cb(ui_AdminLoginId, ui_service_login_id_ready_cb, LV_EVENT_READY, NULL);
    lv_obj_add_event_cb(ui_AdminLoginPass, ui_service_login_pass_ready_cb, LV_EVENT_READY, p_ctrl);

    /* PREPROCESS: runs before the text area deletes a digit, so only * on an already empty box goes back. */
    lv_obj_add_event_cb(ui_AdminLoginPass, ui_service_login_pass_key_cb, LV_EVENT_KEY | LV_EVENT_PREPROCESS, NULL);
}

/***********************************************************************************************************************
 * Empties the text areas and leaves only the shown screen's ones in the keypad group: an empty group drops keys. Home
 * gets ui_InputField, which only submits while Input is shown. No group (no keypad) leaves focus alone. Called under
 * the lock.
 **********************************************************************************************************************/
static void ui_service_inputs_reset(lv_group_t *p_group, ui_service_screen_t screen, bool keep_input)
{
    if (!keep_input)
    {
        lv_textarea_set_text(ui_InputField, "");
    }
    lv_textarea_set_text(ui_AdminLoginId, "");
    lv_textarea_set_text(ui_AdminLoginPass, "");

    if (NULL == p_group)
    {
        return;
    }

    lv_group_remove_all_objs(p_group);
    switch (screen)
    {
        case UI_SERVICE_SCREEN_HOME:
        case UI_SERVICE_SCREEN_INPUT:
            lv_group_add_obj(p_group, ui_InputField);
            lv_group_focus_obj(ui_InputField);
            break;
        case UI_SERVICE_SCREEN_ADMIN_LOGIN:
            lv_group_add_obj(p_group, ui_AdminLoginId);
            lv_group_add_obj(p_group, ui_AdminLoginPass);
            lv_group_focus_obj(ui_AdminLoginId);
            break;
        default:
            break;
    }
}

/***********************************************************************************************************************
 * # on Input: hand a non-empty entry to the caller. On Home the field only collects digits. Runs in the LVGL task.
 **********************************************************************************************************************/
static void ui_service_input_ready_cb(lv_event_t *p_event)
{
    const ui_service_instance_ctrl_t *const p_ctrl = lv_event_get_user_data(p_event);
    const char *const                       p_text = lv_textarea_get_text(ui_InputField);

    if ((lv_scr_act() == ui_Input) && ('\0' != p_text[0]) && (NULL != p_ctrl->p_submit_cb))
    {
        p_ctrl->p_submit_cb(UI_SERVICE_SCREEN_INPUT, p_text, NULL, p_ctrl->p_submit_context);
    }
}

/***********************************************************************************************************************
 * # on the admin ID: continue with the password. Runs in the LVGL task.
 **********************************************************************************************************************/
static void ui_service_login_id_ready_cb(lv_event_t *p_event)
{
    (void)p_event;
    lv_group_focus_obj(ui_AdminLoginPass);
}

/***********************************************************************************************************************
 * # on the admin password: hand ID and password to the caller, or go back to an empty ID. Runs in the LVGL task.
 **********************************************************************************************************************/
static void ui_service_login_pass_ready_cb(lv_event_t *p_event)
{
    const ui_service_instance_ctrl_t *const p_ctrl = lv_event_get_user_data(p_event);
    const char *const                       p_id   = lv_textarea_get_text(ui_AdminLoginId);
    const char *const                       p_pass = lv_textarea_get_text(ui_AdminLoginPass);

    if ('\0' == p_id[0])
    {
        lv_group_focus_obj(ui_AdminLoginId);
    }
    else if (('\0' != p_pass[0]) && (NULL != p_ctrl->p_submit_cb))
    {
        p_ctrl->p_submit_cb(UI_SERVICE_SCREEN_ADMIN_LOGIN, p_id, p_pass, p_ctrl->p_submit_context);
    }
}

/***********************************************************************************************************************
 * * on an empty admin password: back to the ID. Runs in the LVGL task.
 **********************************************************************************************************************/
static void ui_service_login_pass_key_cb(lv_event_t *p_event)
{
    const char *p_text = lv_textarea_get_text(ui_AdminLoginPass);

    if ((LV_KEY_BACKSPACE == lv_event_get_key(p_event)) && ('\0' == p_text[0]))
    {
        lv_group_focus_obj(ui_AdminLoginId);
    }
}
#endif
